compile.workshop:
variables {
    global:
        0: g
}

rule ("boolean arguments") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("{0}", False));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} x", False));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} x", False));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} x", False));
        Big Message(Event Player, Custom String("{0} x", False));
        Big Message(Event Player, Custom String("{0} x", True));
        Big Message(Event Player, Custom String("{0} 3", False));
        Big Message(Event Player, Custom String("{0} {1} 3", True, Global.g));
        Big Message(Event Player, Custom String("{0} {1}", Global.g, False));
        Big Message(Event Player, Custom String("{0} y", True));
    }
}

rule ("non-boolean constants fold") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("3 x"));
        Big Message(Event Player, Custom String("a x"));
        Big Message(Event Player, Custom String("{0} x", Vector(1, 2, 3)));
        Big Message(Event Player, Custom String("{0} x", Hero(Reaper)));
    }
}

//Strict optimizations enabled
rule ("strict") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("{0} x", False));
        Big Message(Event Player, Custom String("{0} x", True));
    }
}

//Strict optimizations disabled
//Optimize for size enabled
rule ("size") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("{0} x", False));
        Big Message(Event Player, Custom String("{0} x", True));
    }
}

//Optimizations disabled
rule ("disabled") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("{0} x", Not(True)));
        Big Message(Event Player, Custom String("{0} x", Compare(1, ==, 1)));
    }
}

